<?php $render=function(array $values,string $prefix='')use(&$render,$e){foreach($values as $key=>$value){$label=$prefix===''?(string)$key:$prefix.'.'.$key;if(is_array($value)){$render($value,$label);}else{?><tr><th scope="row"><?= $e(ucwords(str_replace(['_','.'],' ',$label))) ?></th><td><?= $e(is_bool($value)?($value?'Yes':'No'):($value===null?'—':$value)) ?></td></tr><?php }}}; ?>
<div class="page-heading"><div><a class="back-link" href="<?= $e($url('admin/audit')) ?>">← Audit log</a><span class="eyebrow">AUDIT EVENT</span><h1><?= $e($event['label']) ?></h1><p><?= $e($event['created_local']->format('d M Y, H:i:s')) ?> IST</p></div></div>
<div class="detail-layout"><section class="card"><div class="card-heading"><div><h2>Event</h2><p>Stored operational context with sensitive fields redacted.</p></div></div><dl class="audit-summary"><div><dt>Actor</dt><dd><?= $e($event['actor_name']??'System') ?></dd></div><div><dt>Action code</dt><dd><code><?= $e($event['action']) ?></code></dd></div><div><dt>Entity</dt><dd><?= $e($event['entity_label']) ?></dd></div></dl></section><section class="card"><div class="card-heading"><div><h2>Structured details</h2></div></div><?php if(!$event['details']):?><div class="empty-state"><h3>No additional details were recorded.</h3></div><?php else:?><div class="table-scroll"><table class="key-value-table"><tbody><?php $render($event['details']);?></tbody></table></div><?php endif;?></section></div>
